    s = s.replace('\\left', '').replace('\\right', '').replace('\\,', '').replace('\\!', '').replace('\\ ', '')
    s = re.sub(r'\\(d|t)frac', r'\\frac', s)
    s = re.sub(r'\\text\{([^}]*)\}', r'\1', s)
    s = re.sub(r'\\mathrm\{([^}]*)\}', r'\1', s)
    s = s.replace('\\boxed', '')
    s = re.sub(r'\s+', '', s)
    s = s.replace('{', '').replace('}', '').replace('^', '').replace('*', '').replace('\\cdot', '').replace('\\times', 'x')
    s = s.rstrip('.').lower()
    return s

def extract_boxed(text):
    idx = text.rfind('\\boxed')
    if idx < 0:
        return None
    i = text.find('{', idx)
    if i < 0:
        return None
    depth = 0; j = i
    while j < len(text):
        if text[j] == '{': depth += 1
        elif text[j] == '}':
            depth -= 1
            if depth == 0:
                return text[i + 1:j]
        j += 1
    return None

def extract_hle_answer(text):
    m = list(re.finditer(r'(?im)^\s*\**\s*answer\s*\**\s*:\s*\**\s*(.+?)\s*\**\s*$', text))
