def run_scicode(code, item, timeout=120):
    spec = {'deps': item['deps'], 'prior': item['prior_code'], 'code': code, 'tests': item['tests'], 'targets': item['targets']}
    with tempfile.TemporaryDirectory() as d:
        sp = os.path.join(d, 'spec.json'); rp = os.path.join(d, 'runner.py')
        with open(sp, 'w') as f: json.dump(spec, f)
        with open(rp, 'w') as f: f.write(SCICODE_RUNNER)
        try:
            p = subprocess.run([sys.executable, rp, sp], capture_output=True, text=True, timeout=timeout, cwd=d)
            out = p.stdout.strip().split('\n')[-1] if p.stdout.strip() else ''
            res = json.loads(out)
        except subprocess.TimeoutExpired:
            return 0, len(item['tests']), ['timeout']
        except Exception as e:
            return 0, len(item['tests']), ['runner-error: ' + repr(e)[:200] + ' ' + (p.stderr[-300:] if 'p' in dir() else '')]
    return res['passed'], res['n'], res['log']

