# ---------------- graders ----------------
def make_grader(c, it):
    k, d, iid = it['kind'], it['data'], it['id']
    if k == 'hle':
        def g(text):
            ans = extract_hle_answer(text)
            gold = d['answer'].strip()
            if d['answer_type'] == 'multipleChoice':
                if ans is None:
                    return {'score': 0.0, 'answer_status': 'invalid'}
                m = re.match(r'\(?\s*([A-J])\b', ans.strip().strip('*'))
                letter = m.group(1) if m else None
                return {'score': 1.0 if letter == gold.strip().upper() else 0.0, 'answer_status': 'answered', 'extracted': ans[:100]}
            if ans is not None and norm_ans(ans) == norm_ans(gold) and norm_ans(gold):
                return {'score': 1.0, 'answer_status': 'answered', 'extracted': ans[:100], 'judge': 'local-exact'}
            if ans is None:
                return {'score': 0.0, 'answer_status': 'invalid', 'judge': 'no-answer-line'}
            rep = c.chat(HLE_JUDGE.format(question=d['question'], response=text[-6000:], correct_answer=gold), model=JUDGE_SIM, item_id=iid, max_tokens=TOK_JUDGE_SIM)
            v = yes_no(rep['text'])
            return {'score': 1.0 if v else 0.0, 'answer_status': 'answered', 'extracted': ans[:100], 'judge': 'llm', 'judge_verdict': v, 'judge_text': rep['text'][-400:], 'evidence': [rep['evidence']]}
        return g
