            if norm_ans(ans) == norm_ans(gold):
                return {'score': 1.0, 'answer_status': 'answered', 'extracted': ans[:100], 'judge': 'local-exact'}
            rep = c.chat(MATH_JUDGE.format(question=d['problem'], gold=gold, answer=ans[:500]), model=JUDGE_SIM, item_id=iid, max_tokens=TOK_JUDGE_SIM)
            v = yes_no(rep['text'])
            return {'score': 1.0 if v else 0.0, 'answer_status': 'answered', 'extracted': ans[:100], 'judge': 'llm', 'judge_verdict': v, 'judge_text': rep['text'][-400:], 'evidence': [rep['evidence']]}
        return g
    if k == 'scicode':
