            rep = c.chat(GDPVAL_JUDGE.format(prompt=d['prompt'].strip(), response=text[:30000], rubric=rubric_txt, n=len(rub)), model=JUDGE_GRADER, item_id=iid, max_tokens=TOK_JUDGE_GRADER)
