                got = 0.0; tot = sum(r['score'] for r in rub)
                if verdicts:
                    for v, r in zip(verdicts, rub):
                        got += r['score'] if str(v).upper().startswith('PASS') else 0
                return {'score': got / tot if tot else 0.0, 'answer_status': 'answered', 'judge_parse': 'partial', 'judge_text': jt[-500:], 'evidence': [rep['evidence']]}
            tot = sum(r['score'] for r in rub)
            got = sum(r['score'] for v, r in zip(verdicts, rub) if str(v).upper().startswith('PASS'))
            return {'score': got / tot if tot else 0.0, 'answer_status': 'answered', 'points': got, 'points_total': tot, 'evidence': [rep['evidence']]}
        return g
    raise ValueError(k)

def chat_kwargs(it):
    k, d = it['kind'], it['data']
    if k == 'hle':
        return {'system': HLE_SYSTEM, 'max_tokens': TOK_HLE}
    if k == 'arxiv':
        return {'max_tokens': TOK_ARXIV}
    if k == 'scicode':
        return {'max_tokens': TOK_SCICODE}
    if k == 'lcb':
        return {'max_tokens': TOK_LCB}
    if k == 'if':
        kw = {'max_tokens': TOK_IF}
        if d.get('system'):
            kw['system'] = d['system']
        if d.get('messages'):
            kw['messages'] = d['messages']
        return kw
    if k == 'gdpval':
        return {'max_tokens': TOK_GDPVAL}
    raise ValueError(k)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--context', required=True)
    ap.add_argument('--output', required=True)
    a = ap.parse_args()
    c = Client(a.context)
    items = build_items()
    results = {}
    lock = threading.Lock()
    partial_path = a.output + '.partial.json'
    if os.path.exists(partial_path):
        try:
            for row in json.load(open(partial_path)).get('items', []):
                if row.get('execution_status') == 'completed':
                    results[row['id']] = row
        except Exception:
            pass

    def persist():
        rows = [results[i['id']] for i in items if i['id'] in results]
        tmp = partial_path + '.tmp'
        with open(tmp, 'w') as f:
            json.dump({'protocol_version': 1, 'items': rows}, f)
        os.replace(tmp, partial_path)

    def run_one(it):
        iid = it['id']
        if iid in results:
            return
        if iid in c.completed_items:
            row = c.item(iid, item_prompt(it), lambda t: 0.0)
        else:
            row = c.item(iid, item_prompt(it), make_grader(c, it), **chat_kwargs(it))
        row['id'] = iid
        row['question_id'] = iid
        row['domain'] = it['domain']
        with lock:
            results[iid] = row
            persist()

    with ThreadPoolExecutor(max_workers=2) as ex:
        list(ex.map(run_one, items))

    rows = []
    for it in items:
        r = results.get(it['id'])
        if r is None:
            r = {'id': it['id'], 'question_id': it['id'], 'score': None, 'execution_status': 'not_run', 'answer_status': 'not_applicable', 'evidence': []}
        rows.append(r)
